const http2 = require('http2');
const fs = require('fs');
const jwt = require('jsonwebtoken');
const { ScadaTelemetryService, OperatorAccess } = require('../services/scada');

const server = http2.createSecureServer({
  key: fs.readFileSync('/etc/ssl/scada.key'),
  cert: fs.readFileSync('/etc/ssl/scada.crt')
});

server.on('stream', async (stream, headers) => {
  const url = new URL(headers[':path'], 'https://grid-scada.energy.internal');

  if (url.pathname === '/scada/monitor') {
    const substationId = url.searchParams.get('substationId');

    const authHeader = headers['authorization'];
    if (!authHeader) {
      stream.respond({ ':status': 401 });
      return stream.end('Operator authorization required');
    }

    let operator;
    try {
      operator = jwt.verify(authHeader.replace('Bearer ', ''), process.env.SCADA_SECRET);
    } catch {
      stream.respond({ ':status': 401 });
      return stream.end('Invalid credentials');
    }

    // Verify operator has jurisdiction over the designated substation
    const isAuthorized = await OperatorAccess.canMonitorSubstation(operator.id, substationId);
    if (!isAuthorized) {
      stream.respond({ ':status': 403 });
      return stream.end('Access denied: operator not authorized for this substation');
    }

    if (substationId && stream.pushAllowed) {
      stream.pushStream({ ':path': `/api/telemetry/substations/${substationId}/metrics.json` }, async (err, pushStream) => {
        if (err) return;
        const telemetry = await ScadaTelemetryService.getSubstationStatus(substationId);
        pushStream.respond({ ':status': 200, 'content-type': 'application/json' });
        pushStream.end(JSON.stringify(telemetry));
      });
    }

    stream.respond({ ':status': 200, 'content-type': 'text/html' });
    stream.end('<html><body>Substation Monitor Ready</body></html>');
  }
});

server.listen(8447);
